package com.sentinelcore.assetservice.entity;
import java.time.LocalDateTime; import java.util.UUID; import jakarta.persistence.*;
@Entity @Table(name="security_reviews") public class SecurityReview { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false,fetch=FetchType.LAZY) private User reviewer; private String scope; private String reviewPeriod; @Column(length=4000) private String findings; @Column(length=4000) private String anomalies; @Enumerated(EnumType.STRING) private SecurityReviewStatus status=SecurityReviewStatus.PENDING; @Column(length=4000) private String comments; private LocalDateTime reviewDate; private LocalDateTime createdAt; @PrePersist void onCreate(){if(createdAt==null)createdAt=LocalDateTime.now(); if(reviewDate==null)reviewDate=createdAt;} public UUID getId(){return id;} public void setId(UUID id){this.id=id;} public User getReviewer(){return reviewer;} public void setReviewer(User v){reviewer=v;} public String getScope(){return scope;} public void setScope(String v){scope=v;} public String getReviewPeriod(){return reviewPeriod;} public void setReviewPeriod(String v){reviewPeriod=v;} public String getFindings(){return findings;} public void setFindings(String v){findings=v;} public String getAnomalies(){return anomalies;} public void setAnomalies(String v){anomalies=v;} public SecurityReviewStatus getStatus(){return status;} public void setStatus(SecurityReviewStatus v){status=v;} public String getComments(){return comments;} public void setComments(String v){comments=v;} public LocalDateTime getReviewDate(){return reviewDate;} public LocalDateTime getCreatedAt(){return createdAt;} }